export type Revision = { id: string; etag: string };

export async function loadRevision(documentId: string): Promise<Revision> {
  const response = await fetch(`/api/documents/${encodeURIComponent(documentId)}/revision`);
  if (!response.ok) throw new Error("Could not load revision");
  const data = (await response.json()) as { revision: string; etag: string };
  return { id: data.revision, etag: data.etag };
}

