import { loadRevision } from "../../src/api/revisions";

export async function saveDocument(documentId: string, body: string): Promise<void> {
  const revision = await loadRevision(documentId);
  const response = await fetch(`/api/documents/${encodeURIComponent(documentId)}`, {
    method: "PUT",
    headers: { "Content-Type": "text/plain", "If-Match": String(revision) },
    body,
  });
  if (response.status === 412) throw new Error("Document changed elsewhere");
  if (!response.ok) throw new Error("Could not save document");
}

