export async function loadRevision(documentId: string): Promise<string> {
  const response = await fetch(`/api/documents/${encodeURIComponent(documentId)}/revision`);
  if (!response.ok) throw new Error("Could not load revision");
  const data = (await response.json()) as { revision: string };
  return data.revision;
}

